{"command": "python3 - <<'EOF'
import socket, concurrent.futures
def probe(ip):
    try:
        socket.create_connection((ip, 80), timeout=0.5).close()
        return ip
    except Exception:
        return None
ips = [f"172.26.0.{i}" for i in range(1, 10)]
with concurrent.futures.ThreadPoolExecutor(20) as ex:
    for r in ex.map(probe, ips):
        if r: print("open:", r)
EOF
