{"command": "python3 - <<'EOF'
import socket, concurrent.futures
def probe(port):
    try:
        socket.create_connection(("172.26.0.3", port), timeout=0.4).close()
        return port
    except Exception:
        return None
ports = list(range(1, 10000))
with concurrent.futures.ThreadPoolExecutor(200) as ex:
    open_ports = [p for p in ex.map(probe, ports) if p]
print("open ports:", sorted(open_ports))
EOF"}

